<script setup>
import { ArrowDownToLine, ArrowUpFromLine, Eye, Package, Plus, Search, X } from 'lucide-vue-next'
import { useStockTransfers } from '@/composables/useStockTransfers'

const {
  transfers, branches, items, selectedTransfer, selectedDispatch, loading, saving, page, pagination,
  searchInput, statusFilter, error, notice, modalError, transferDialog, dispatchDialog, receiveDialog,
  detailDialog, transferDate, movementDate, transferForm, movementLines, selectedDispatchID,
  editingTransferID, totalMovementQty, totalPages, formatDateLabel, statusLabel, statusClass, dispatchHasRemaining,
  loadTransfers, openCreate, openEdit, changeSourceBranch, addItem, removeItem, saveTransfer,
  openDetails, openDispatch, openReceive, selectDispatch, saveMovement, cancelTransfer, applySearch, applyStatus,
} = useStockTransfers()
</script>

<template>
  <section class="space-y-6">
    <header class="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
      <div class="flex items-center gap-3"><ArrowUpFromLine :size="25" class="text-blue-600" aria-hidden="true" /><div><h1 class="text-2xl font-bold text-slate-800">Stock Transfers</h1><p class="text-sm text-slate-500">Move inventory between branches with separate dispatch and receipt steps.</p></div></div>
      <button type="button" class="inline-flex min-h-10 items-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-700" @click="openCreate"><Plus :size="18" aria-hidden="true" />New Transfer</button>
    </header>

    <div v-if="notice" role="status" class="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{{ notice }}</div>
    <div v-if="error" role="alert" class="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{{ error }}</div>

    <form class="grid gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-[minmax(14rem,1fr)_12rem_auto]" @submit.prevent="applySearch">
      <label class="relative"><span class="sr-only">Search transfers</span><Search :size="17" class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" aria-hidden="true" /><input v-model="searchInput" class="min-h-10 w-full rounded-lg border border-slate-300 py-2.5 pl-9 pr-3 text-sm" placeholder="Transfer number or branch" /></label>
      <label class="sr-only" for="transfer-status-filter">Filter by status</label><select id="transfer-status-filter" v-model="statusFilter" class="min-h-10 rounded-lg border border-slate-300 px-3 text-sm" @change="applyStatus"><option value="">All statuses</option><option value="draft">Draft</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select>
      <button class="min-h-10 rounded-lg border border-slate-300 px-4 py-2.5 text-sm font-medium hover:bg-slate-50">Search</button>
    </form>

    <div class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <header class="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h2 class="font-semibold text-slate-800">Transfer list</h2><p class="text-xs text-slate-500">{{ pagination.total || 0 }} transfer(s)</p></div><button type="button" class="text-sm text-blue-700 underline disabled:opacity-50" :disabled="loading" @click="loadTransfers">Refresh</button></header>
      <div class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Transfer number</th><th class="px-5 py-3">From branch</th><th class="px-5 py-3">To branch</th><th class="px-5 py-3">Date</th><th class="px-5 py-3">Total qty</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Actions</th></tr></thead><tbody class="divide-y divide-slate-100">
