        <tr v-for="transfer in transfers" v-else :key="transfer.id" class="hover:bg-slate-50"><td class="px-5 py-4 font-semibold text-slate-800">{{ transfer.transfer_number }}</td><td class="px-5 py-4">{{ transfer.from_branch_name }}</td><td class="px-5 py-4">{{ transfer.to_branch_name }}</td><td class="px-5 py-4">{{ formatDateLabel(transfer.transfer_date) }}</td><td class="px-5 py-4">{{ transfer.total_qty }}</td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-medium capitalize" :class="statusClass(transfer.status)">{{ statusLabel(transfer.status) }}</span></td><td class="px-5 py-4"><div class="flex flex-wrap gap-x-3 gap-y-2"><button type="button" class="inline-flex items-center gap-1 text-blue-700 hover:underline" @click="openDetails(transfer)"><Eye :size="16" aria-hidden="true" />Details</button><button v-if="transfer.status === 'draft'" type="button" class="text-blue-700 hover:underline" @click="openEdit(transfer)">Edit</button><button v-if="transfer.status === 'draft' || transfer.status === 'in_progress'" type="button" class="text-blue-700 hover:underline" @click="openDispatch(transfer)">Dispatch</button><button v-if="transfer.status === 'in_progress'" type="button" class="text-blue-700 hover:underline" @click="openReceive(transfer)">Receive</button><button v-if="transfer.status === 'draft'" type="button" class="text-red-600 hover:underline" @click="cancelTransfer(transfer)">Cancel</button></div></td></tr>
