        <form @submit.prevent="saveTransfer"><div class="space-y-5 p-6">
          <div v-if="modalError" role="alert" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ modalError }}</div>
          <div class="grid gap-4 sm:grid-cols-3"><label class="space-y-1.5 text-sm font-medium text-slate-700">Source branch<select required class="min-h-10 w-full rounded-lg border border-slate-300 px-3 py-2 font-normal" :value="transferForm.from_branch_id" @change="changeSourceBranch($event.target.value)"><option value="" disabled>Select source</option><option v-for="branch in branches" :key="branch.id" :value="branch.id">{{ branch.name }}</option></select></label><label class="space-y-1.5 text-sm font-medium text-slate-700">Destination branch<select v-model="transferForm.to_branch_id" required class="min-h-10 w-full rounded-lg border border-slate-300 px-3 py-2 font-normal"><option value="" disabled>Select destination</option><option v-for="branch in branches" :key="branch.id" :value="branch.id" :disabled="Number(branch.id) === Number(transferForm.from_branch_id)">{{ branch.name }}</option></select></label><label class="space-y-1.5 text-sm font-medium text-slate-700">Transfer date<input v-model="transferDate" required type="date" class="min-h-10 w-full rounded-lg border border-slate-300 px-3 py-2 font-normal" /></label></div>
