ass="text-right text-sm text-slate-600">Total dispatch qty: <strong>{{ totalMovementQty }}</strong></p></div><footer class="flex justify-end gap-3 border-t border-slate-200 px-6 py-4"><button type="button" class="rounded-lg border border-slate-300 px-4 py-2 text-sm" @click="dispatchDialog = false">Close</button><button type="submit" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-60" :disabled="saving || !movementLines.length">{{ saving ? 'Posting…' : 'Post Dispatch' }}</button></footer></form></section></div>

