medium">{{ line.sku }} — {{ line.item_name }} ({{ line.unit }})</p><p class="text-xs text-slate-500">Remaining on this dispatch: {{ line.remaining_qty }}</p></div><label class="text-xs font-medium text-slate-600">Received qty<input v-model="line.qty" type="number" min="1" :max="line.remaining_qty" step="1" class="mt-1 min-h-9 w-full rounded-md border border-slate-300 px-2.5 py-1.5 text-sm font-normal" /></label></div><p v-if="selectedDispatchID && !movementLines.length" class="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800">This dispatch has been fully received.</p><p class="text-right text-sm text-slate-600">Total received qty: <strong>{{ totalMovementQty }}</strong></p></div><footer class="flex justify-end gap-3 border-t border-slate-200 px-6 py-4"><button type="button" class="rounded-lg border border-slate-300 px-4 py-2 text-sm" @click="receiveDialog = false">Close</button><button type="submit" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-60" :disabled="saving || !movementLines.length">{{ saving ? 'Posting…' : 'Post Receipt' }}</button></footer></form></section></div>

    <div v-if="detailDialog && selectedTransfer" class="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-slate-950/50 p-4" @click.self="detailDialog = false"><section role="dialog" aria-modal="true" aria-labelledby="transfer-detail-title" class="my-auto max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-xl bg-white shadow-xl"><header class="flex items-start justify-between border-b border-slate-200 px-6 py-5"><div><h2 id="transfer-detail-title" class="text-lg font-semibold text-slate-800">{{ selectedTransfer.transfer_number }}</h2><p class="text-sm text-slate-500">{{ selectedTransfer.from_branch_name }} → {{ selectedTransfer.to_branch_name }}</p></div><button type="button" aria-label="Close" class="rounded-lg p-2 text-slate-500 hover:bg-slate-100" @click="detailDialog = false"><X :size="19" /></button></header><div class="space-y-6 p-6"><div class="grid gap-3 text-sm sm:grid-cols-3"><p><strong>Date:</strong> {{ formatDateLabel(selectedTransfer.transfer_date) }}</p><p><strong>Status:</strong> <span class="capitalize">{{ statusLabel(selectedTransfer.status) }}</span></p><p><strong>Planned quantity:</strong> {{ selectedTransfer.total_qty }}</p></div><div><h3 class="mb-2 font-semibold text-slate-800">Transfer quantities</h3><div v-for="line in selectedTransfer.lines" :key="line.item_id" class="grid gap-1 border-t border-slate-100 py-3 text-sm sm:grid-cols-5"><span>{{ line.sku }} — {{ line.item_name }} ({{ line.unit }})</span><span>Planned {{ line.qty }}</span><span>Dispatched {{ line.dispatched_qty }}</span><span>In transit {{ line.in_transit_qty }}</span><span>Received {{ line.received_qty }}</span></div></div><div><h3 class="mb-2 font-semibold text-slate-800">Dispatches</h3><div v-for="dispatch in selectedTransfer.dispatches" :key="dispatch.gd_header_id" class="mb-2 rounded-lg border border-slate-200 p-3"><p class="font-medium">{{ dispatch.gd_number }} · {{ formatDateLabel(dispatch.gd_date) }}</p><p v-for="line in dispatch.lines" :key="line.item_id" class="mt-1 text-sm text-slate-600">{{ line.sku }} — shipped {{ line.qty }}, received {{ line.received_qty }}, remaining {{ line.remaining_qty }}</p></div><p v-if="!selectedTransfer.dispatches.length" class="text-sm text-slate-500">No dispatches have been posted.</p></div><div><h3 class="mb-2 font-semibold text-slate-800">Receipt documents</h3><p v-for="receipt in selectedTransfer.receipts" :key="receipt.id" class="border-t border-slate-100 py-2 text-sm text-slate-600">{{ receipt.receipt_number }} · {{ receipt.gd_number }} · {{ formatDateLabel(receipt.receipt_date) }} · {{ receipt.total_qty }} received</p><p v-if="!selectedTransfer.receipts.length" class="text-sm text-slate-500">No receipts have been posted.</p></div><div class="flex justify-end"><button v-if="selectedTransfer.status === 'draft' || selectedTransfer.status === 'in_progress'" type="button" class="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white" @click="detailDialog = false; openDispatch(selectedTransfer)"><ArrowUpFromLine :size="16" aria-hidden="true" />Dispatch</button><button v-if="selectedTransfer.status === 'in_progress'" type="button" class="ml-2 inline-flex items-center gap-2 rounded-lg border border-blue-600 px-4 py-2 text-sm font-semibold text-blue-700" @click="detailDialog = false; openReceive(selectedTransfer)"><ArrowDownToLine :size="16" aria-hidden="true" />Receive</button></div></div></section></div>
  </section>
</template>
